function setZeroesWithSets(matrix) {
  const rows = new Set(), cols = new Set();
  matrix.forEach((row, r) => row.forEach((v, c) => {
    if (v === 0) { rows.add(r); cols.add(c); }
  }));
  matrix.forEach((row, r) => row.forEach((_, c) => {
    if (rows.has(r) || cols.has(c)) matrix[r][c] = 0;
  }));
}

function setZeroes(matrix) {
  const rows = matrix.length, cols = matrix[0].length;
  let firstColHasZero = false;
  for (let r = 0; r < rows; r++) {                // 1. record markers
    if (matrix[r][0] === 0) firstColHasZero = true;
    for (let c = 1; c < cols; c++) {
      if (matrix[r][c] === 0) {
        matrix[r][0] = 0;
        matrix[0][c] = 0;
      }
    }
  }
  for (let r = rows - 1; r >= 0; r--) {           // 2. apply, bottom-up
    for (let c = cols - 1; c >= 1; c--) {
      if (matrix[r][0] === 0 || matrix[0][c] === 0) matrix[r][c] = 0;
    }
    if (firstColHasZero) matrix[r][0] = 0;
  }
}

